function setValue(valueType) {
    try {
    	    let Variable = JSON.parse(source.getVariable());
        let valid = false;
        let sourceName;
        let sourceValue;

        for(let i = 0; i < data.length; i++) {
            if(data[i][1] === valueType) {
                valid = true;
                sourceName = data[i][0];
                sourceValue = data[i][2];
                break;
            }
        }

        if (valid) {

            Variable.Variable.Source.type = valueType;
            Variable.Variable.Source.name = sourceName;
            Variable.Variable.Source.value = sourceValue;

            let jsonStr = JSON.stringify(Variable, null, "\t");
            source.setVariable(jsonStr);
            java.toast("已切换到: \n" + sourceName);
        } else {
            java.toast("无效的来源类型");
        }
    } catch (err) {
        java.toast("设置来源错误：\n" + err);
        java.log(err);
    }
}
function getValue() {
	   try{
	   	    let Variable = JSON.parse(source.getVariable());
	   	    let value = Variable.Variable.Source.type;
	   	    let sname;
	   	    for( let i = 0; i < data.length; i ++ ) {
	   	    	    if( data[i] === value ) {
	   	    	    	    sname = data[i][0];
	   	    	    	    break;
	   	    	    	}
	   	    	}
	   	    	if ( sname == undefined ) {
	   	    		    sname = Variable.Variable.Source.name;
	   	    		}
	   	    	java.log(sname);
	   	    java.toast("当前来源：\n" + sname);
	   	} catch( e ) {
	   		   java.log(e);
	   	    java.toast("当前未选择来源！");
	   	}
	}

